-- ============================================================================
-- H2: Occupational Hygiene: Noise, Chemical & Heat Exposure joins the
-- catalogue, the SECOND course of the HSE module.
--
-- Catalogue row (module 'hse'; path_order 62, directly above the HSE module's
-- own safetystats at 61; prereq_slug NULL, the carried-over answer "no hard
-- prerequisite inside a module"; school left at its default, as every
-- Facilities, Economics, Assurance and HSE course leaves it, so the fees are
-- the published school-level rows) plus the three capstones and their eighteen
-- graded fields, generated by tools/course-waves/hygiene/gen_course.py from the
-- ENGINE'S OWN RUN (h2_capstone.mjs through the vendored engines/hse/exposure.js,
-- sha-identical with petrolord-engines 16fd6c9), which it refuses to write
-- unless fields.json carries exactly that run's values and the tolerance
-- gradedTolerance.js derives. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/hygiene, because the 78 lessons, the teaching lab and
-- its three explorer panels ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. An exposure figure is a measurement read
-- against a criterion and it means nothing until the criterion is named, so the
-- course teaches what the noise dose is once the criterion is named
-- (Associate), how protection and chemical averages are each computed on the
-- metric their own source prints (Professional), and what a shift that is not
-- eight hours does to a trigger, a limit and a mixture (Expert).
--
-- THE ENGINE. engines/hse/exposure.js, vendored sha-identical with
-- petrolord-engines 16fd6c9. It imports nothing and embeds no licensed limit
-- table: every limit in this course is typed as an input from a public OSHA or
-- NIOSH value. The reference duration, the noise dose, the printed
-- dose-to-average coefficients 16.61 and 10.0, the threshold that decides what
-- is integrated at all, LEX,8h, the protector methods, the chemical averages,
-- the mixture index and the Brief and Scala reduction factors are each
-- reproduced by a value their own source prints.
--
-- WHAT IS GRADED, AND THE LINE THIS COURSE DOES NOT CROSS. UTOROGU (Associate)
-- grades three noise doses under three named criteria, the two time weighted
-- average sound levels two of them correspond to, and the minutes still
-- available at the loudest sound level. AMUKPE (Professional) grades a daily
-- and a weekly LEX, the OSHA fifty percent field derated sound level, an
-- eight-hour and a fifteen-minute chemical average and a mixture index. OSIOKA
-- (Expert) grades two one-hour time weighted averages of STATED readouts, the
-- extended-shift action level, the whole-shift noise dose, one adjusted limit
-- and the mixture index against the adjusted limits.
--
-- NO graded field passes through a NIOSH heat recommended alert limit or
-- recommended exposure limit, a margin against either, an exceedance verdict,
-- or a wet bulb globe temperature built from thermometer readings. Those
-- equations and those weights are TAUGHT and checked for transcription only:
-- no public printed value reproduces them, and NIOSH's own worked example
-- disagrees with its own section 8.1 equation, so a learner following the
-- document's own figure would be marked wrong. The NIOSH derating by protector
-- type, OSHA dual protection and the Brief and Scala weekly factor on its own
-- are taught and graded nowhere. The generator refuses a key, a label, a unit
-- or a prompt that crosses that line.
--
-- All eighteen graded values were swept against every number the digest prints
-- and against every number handed to a learner in a prompt, a dataset, a title
-- or a label, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('hygiene', 'Occupational Hygiene: Noise, Chemical & Heat Exposure', 'hse', 62, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'hygiene', 'beginner', 'associate',
  'UTOROGU, one operator''s eight-hour dosimeter day in a gas compressor house',
  'What the noise dose is, once the criterion is named',
  'UTOROGU, a gas compressor house. One operator wore a dosimeter for a full shift of eight hours, logged as five periods. Each period carries the A-weighted sound level the instrument recorded and how long it lasted: period 1, 86.7 dBA for 2.35 hours; period 2, 92.4 dBA for 1.6 hours; period 3, 83.3 dBA for 2.2 hours; period 4, 96.3 dBA for 0.55 hours; period 5, 78.6 dBA for 1.3 hours. The loudest sound level of the day is 96.3 dBA. Read this one record three ways. The OSHA permissible exposure limit setup has a criterion of 90 dBA, a decibel exchange rate of 5 dB and a threshold of 90 dBA. The OSHA action level setup has the same criterion of 90 dBA and the same decibel exchange rate of 5 dB, a threshold of 80 dBA and a limit of 50 percent. The NIOSH noise REL setup has a criterion of 85 dBA, a decibel exchange rate of 3 dB and a threshold of 80 dBA. A period whose sound level is under a setup''s threshold is not integrated by that setup at all. The reference duration at a sound level is eight hours divided by 2 raised to the level less the criterion over the decibel exchange rate. Use the coefficients the sources print when you turn a noise dose into a time weighted average sound level: 16.61 for the two OSHA setups and 10.0 for the NIOSH noise REL setup. Report six values: the noise dose of the day on the OSHA permissible exposure limit setup, as a percentage; the time weighted average sound level that noise dose corresponds to on the same setup; the noise dose of the same day on the OSHA action level setup; the noise dose of the same day on the NIOSH noise REL setup; the time weighted average sound level on the NIOSH noise REL setup; and the minutes still available at the loudest sound level of the day once the OSHA permissible exposure limit noise dose is spent, which is one less that noise dose as a fraction, times the reference duration at that sound level, times sixty. The three noise doses as percentages, the two sound levels in dBA and the last value in minutes, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','utorogu_osha_pel_dose_pct', 'label','The noise dose of the day on the OSHA permissible exposure limit setup', 'unit','percent', 'expected',44.3602055155184, 'tol',5e-07),
    jsonb_build_object('key','utorogu_osha_pel_twa_dba', 'label','The time weighted average sound level that noise dose corresponds to on the OSHA permissible exposure limit setup', 'unit','dBA', 'expected',84.13656285746234, 'tol',5e-07),
    jsonb_build_object('key','utorogu_action_level_dose_pct', 'label','The noise dose of the same day on the OSHA action level setup', 'unit','percent', 'expected',73.81407352757833, 'tol',5e-07),
    jsonb_build_object('key','utorogu_niosh_rel_dose_pct', 'label','The noise dose of the same day on the NIOSH noise REL setup', 'unit','percent', 'expected',266.2009704602468, 'tol',5e-07),
    jsonb_build_object('key','utorogu_niosh_rel_twa_dba', 'label','The time weighted average sound level on the NIOSH noise REL setup', 'unit','dBA', 'expected',89.25209634402225, 'tol',5e-07),
    jsonb_build_object('key','utorogu_pel_minutes_left_min', 'label','The minutes still available at the loudest sound level of the day once the OSHA permissible exposure limit noise dose is spent', 'unit','minutes', 'expected',111.51388851232277, 'tol',5e-07)
  )
),
(
  'hygiene', 'intermediate', 'professional',
  'AMUKPE, a maintenance crew on a floating production vessel, with a survey, a week of daily values and three personal air samples',
  'Protection and chemicals, each on the metric its own source prints',
  'AMUKPE, a maintenance crew on a floating production vessel. A task-based survey covered one working day in five tasks, each with the A-weighted equivalent sound level and its length: task 1, 89.6 dBA for 1.8 hours; task 2, 82.3 dBA for 3.9 hours; task 3, 98.2 dBA for 0.35 hours; task 4, 76.4 dBA for 2.45 hours; task 5, 93.1 dBA for 0.7 hours. The daily figure wanted is LEX,8h, which counts every task, has no threshold and normalises to eight hours whatever the day was. The same worker''s five daily values for the week are 87.9, 84.6, 89.3, 82.2 and 85.7 dBA, and the weekly figure is taken over the statutory divisor of five days. A dosimeter on the same worker returned an OSHA permissible exposure limit noise dose of 612.4 percent; turn that into a time weighted average sound level with the printed coefficient 16.61 on the criterion of 90 dBA before any protector credit is taken. The earmuff issued carries a labelled noise reduction rating of 29 dB, and the estimate wanted is the OSHA fifty percent field derating for A-weighted data, which credits half of the labelled rating less seven. Three personal air samples follow. Benzene, over part of the shift: sample 1, 0.86 ppm for 2.4 hours; sample 2, 0.34 ppm for 3.15 hours; sample 3, 1.73 ppm for 0.8 hours. The unsampled part of the shift counts as zero and the divisor is the eight hours the regulation writes. Toluene, short term: reading 1, 212 ppm for 6 minutes; reading 2, 148 ppm for 5.5 minutes. The remainder of the fifteen-minute window counts as zero. The mixture, each limit typed as an input: toluene at 61.4 ppm against a limit of 200 ppm; xylene at 28.3 ppm against a limit of 100 ppm; cyclohexane at 97.4 ppm against a limit of 300 ppm. Report six values: the daily LEX,8h of the survey day; the weekly value over the five stated days; the sound level under the earmuff by the OSHA fifty percent field derating; the eight-hour time weighted average benzene concentration; the fifteen-minute short term average toluene concentration; and the additive mixture index of the three solvents against the limits as typed. The two LEX values and the derated sound level in dBA, the two concentrations in ppm and the index as a plain number, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','amukpe_lex_8h_dba', 'label','The daily noise exposure level LEX,8h of the survey day', 'unit','dBA', 'expected',88.8596336786288, 'tol',5e-07),
    jsonb_build_object('key','amukpe_lex_weekly_dba', 'label','The weekly noise exposure level over the five stated daily values', 'unit','dBA', 'expected',86.61553376952014, 'tol',5e-07),
    jsonb_build_object('key','amukpe_field_derated_exposure_dba', 'label','The sound level under the earmuff by the OSHA fifty percent field derating', 'unit','dBA', 'expected',92.07265437345556, 'tol',5e-07),
    jsonb_build_object('key','amukpe_benzene_twa8h_ppm', 'label','The eight-hour time weighted average benzene concentration', 'unit','ppm', 'expected',0.564875, 'tol',5e-07),
    jsonb_build_object('key','amukpe_toluene_stel_ppm', 'label','The fifteen-minute short term average toluene concentration', 'unit','ppm', 'expected',139.06666666666666, 'tol',5e-07),
    jsonb_build_object('key','amukpe_mixture_index', 'label','The additive mixture index of the three solvents against the limits as typed', 'unit','index', 'expected',0.9146666666666667, 'tol',5e-07)
  )
),
(
  'hygiene', 'advanced', 'expert',
  'OSIOKA, a hot-season turnaround on extended shifts, with stated heat stress readouts and a full-shift dosimeter record',
  'The shift that is not eight hours, and the readings a heat stress assessment starts from',
  'OSIOKA, a flow station turnaround in the hot season. The crew works shifts of 11.25 hours, four a week, so 45 hours in the week. The hardest hour of the shift is logged as three work periods, each carrying the wet bulb globe temperature the instrument read out and the metabolic rate the task table gives: period 1, 31.6 degrees C at 418 watts for 22 minutes; period 2, 29.3 degrees C at 305 watts for 23 minutes; period 3, 26.9 degrees C at 165 watts for 15 minutes. Those readouts are stated, so nothing here has to be built from a globe, a natural wet bulb and a dry bulb reading. A dosimeter covered the whole shift on the OSHA action level setup, a criterion of 90 dBA, a decibel exchange rate of 5 dB and a threshold of 80 dBA: period 1, 85.2 dBA for 3.4 hours; period 2, 88.6 dBA for 2.1 hours; period 3, 81.6 dBA for 3.3 hours; period 4, 91.7 dBA for 0.8 hours; period 5, 77.8 dBA for 1.65 hours. The whole shift is summed as it stands, with no rescaling to eight hours. For a shift longer than eight hours the OSHA action level is 16.61 times the base 10 logarithm of 50 divided by 12.5 times the shift hours, plus 90. Full-shift average concentrations of three solvents, each limit typed as an input: xylene at 24.3 ppm against a limit of 100 ppm; toluene at 41.8 ppm against a limit of 200 ppm; n-hexane at 96.5 ppm against a limit of 500 ppm. The xylene limit of 100 ppm is the one to adjust. The Brief and Scala daily reduction factor is 8 over the shift hours, times 24 less the shift hours, over 16; the weekly factor is 40 over the weekly hours, times 168 less the weekly hours, over 128. Each factor is capped at 1 and the more protective of the two governs. Report six values: the one-hour time weighted average of the three stated wet bulb globe temperature readouts; the one-hour time weighted average of the three stated metabolic rates; the OSHA action level for this shift; the noise dose of the whole shift on the OSHA action level setup; the xylene limit multiplied by the governing Brief and Scala reduction factor; and the additive mixture index of the three solvents against limits each multiplied by that same governing factor. The temperature in degrees C, the metabolic rate in watts, the action level in dBA, the noise dose as a percentage, the adjusted limit in ppm and the index as a plain number, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','osioka_wbgt_twa_c', 'label','The one-hour time weighted average of the three stated wet bulb globe temperature readouts', 'unit','degrees C', 'expected',29.543333333333333, 'tol',5e-07),
    jsonb_build_object('key','osioka_metabolic_twa_w', 'label','The one-hour time weighted average of the three stated metabolic rates', 'unit','watts', 'expected',311.43333333333334, 'tol',5e-07),
    jsonb_build_object('key','osioka_extended_action_level_dba', 'label','The OSHA action level for this shift, which is longer than eight hours', 'unit','dBA', 'expected',82.54057305810645, 'tol',5e-07),
    jsonb_build_object('key','osioka_extended_action_dose_pct', 'label','The noise dose of the whole shift on the OSHA action level setup', 'unit','percent', 'expected',68.99765774496588, 'tol',5e-07),
    jsonb_build_object('key','osioka_adjusted_limit_ppm', 'label','The xylene limit multiplied by the governing Brief and Scala reduction factor', 'unit','ppm', 'expected',56.666666666666664, 'tol',5e-07),
    jsonb_build_object('key','osioka_adjusted_mixture_index', 'label','The additive mixture index of the three solvents against the adjusted limits', 'unit','index', 'expected',1.138235294117647, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
